        'ai.settings.lead1': {
            en: 'Default: the app calls your Supabase project\'s Edge Function ai-patient-draft, which validates the logged-in clinic user server-side and calls OpenAI there (never from the browser). Set OPENAI_API_KEY only in Supabase secrets. If the function is missing or errors, Joyful Smile falls back to the optional HTTPS proxy below, then offline demo templates.',
            'zh-CN': '默认：应用调用您 Supabase 项目的 Edge 函数 ai-patient-draft，在服务端校验已登录诊所用户并在该处调用 OpenAI（绝不会在浏览器中）。OPENAI_API_KEY 仅设置在 Supabase 密钥中。若函数缺失或出错，乐意会回退到下方可选 HTTPS 代理，再回退到离线演示模板。',
            'zh-Hant': '預設：應用程式呼叫您 Supabase 專案的 Edge 函式 ai-patient-draft，在伺服器端校驗已登入診所使用者並於該處呼叫 OpenAI（絕不會在瀏覽器中）。OPENAI_API_KEY 僅設定在 Supabase 秘密中。若函式缺失或出錯，樂意會回退到下方可選 HTTPS 代理，再回退到離線示範範本。'
        },
        'ai.settings.deployTitle': { en: 'Deploy on your Supabase project', 'zh-CN': '在您的 Supabase 项目上部署', 'zh-Hant': '在您的 Supabase 專案上部署' },
        'ai.settings.advanced': {
            en: 'Advanced: custom HTTPS gateway (same JSON body + { "message": "…" } response). Include workflow: "memo" plus memoAction, memoBody for memo rewriting.',
            'zh-CN': '高级：自定义 HTTPS 网关（相同 JSON 正文 + { "message": "…" } 响应）。备忘改写需包含 workflow: "memo" 以及 memoAction、memoBody。',
            'zh-Hant': '進階：自訂 HTTPS 閘道（相同 JSON 正文 + { "message": "…" } 回應）。備忘改寫需包含 workflow: "memo" 以及 memoAction、memoBody。'
        },
        'ai.settingsAdvancedHtml': {
            en: 'Advanced: custom HTTPS gateway (same JSON body + <code>{ "message": "…" }</code> response). Include <code>workflow: "memo"</code> plus <code>memoAction</code>, <code>memoBody</code> for memo rewriting.',
            'zh-CN': '高级：自定义 HTTPS 网关（相同 JSON 正文 + <code>{ "message": "…" }</code> 响应）。备忘改写需包含 <code>workflow: "memo"</code> 以及 <code>memoAction</code>、<code>memoBody</code>。',
            'zh-Hant': '進階：自訂 HTTPS 閘道（相同 JSON 正文 + <code>{ "message": "…" }</code> 回應）。備忘改寫需包含 <code>workflow: "memo"</code> 以及 <code>memoAction</code>、<code>memoBody</code>。'
        },
