            'zh-Hant': '將依次開啟每位病人 — 使用<strong>開啟 WhatsApp Web</strong>在新分頁中預填訊息（桌面版使用 web.whatsapp.com）。若只看到 QR code，請先在 web.whatsapp.com 登入，再按按鈕。使用<strong>下一位病人</strong>繼續所選清單。'
