        'appt.recall.waWebHintHtml': {
            en: '<strong>WhatsApp Web:</strong> Opens a new browser tab with this patient and message filled in. If you only see a QR code, open <a href="https://web.whatsapp.com/" target="_blank" rel="noopener noreferrer" style="color:#047857;text-decoration:underline;">web.whatsapp.com</a> in another tab, scan to log in, then click <strong>Open WhatsApp Web</strong> again.',
            'zh-CN': '<strong>WhatsApp Web：</strong>在新标签页打开并预填此患者及消息。若只看到二维码，请在另一标签页打开 <a href="https://web.whatsapp.com/" target="_blank" rel="noopener noreferrer" style="color:#047857;text-decoration:underline;">web.whatsapp.com</a> 扫码登录，再点击<strong>打开 WhatsApp Web</strong>。',
            'zh-Hant': '<strong>WhatsApp Web：</strong>在新分頁開啟並預填此病人及訊息。若只看到 QR code，請在另一分頁開啟 <a href="https://web.whatsapp.com/" target="_blank" rel="noopener noreferrer" style="color:#047857;text-decoration:underline;">web.whatsapp.com</a> 掃碼登入，再按<strong>開啟 WhatsApp Web</strong>。'
        },
