        'ai.settings.deployStepsHtml': {
            en: '<li>Install CLI, then <code>supabase login</code> and <code>supabase link</code> to your project.</li><li>Add secret: Dashboard → Functions → Secrets → <code>OPENAI_API_KEY</code> (optional <code>OPENAI_MODEL</code>).</li><li>Deploy: <code>supabase functions deploy ai-patient-draft</code></li><li>Use the same anon key/project URL already in Joyful Smile (no key change needed).</li>',
            'zh-CN': '<li>安装 CLI，然后 <code>supabase login</code> 和 <code>supabase link</code> 连接到您的项目。</li><li>添加密钥：Dashboard → Functions → Secrets → <code>OPENAI_API_KEY</code>（可选 <code>OPENAI_MODEL</code>）。</li><li>部署：<code>supabase functions deploy ai-patient-draft</code></li><li>使用乐意中已有的 anon key / 项目 URL（无需更改密钥）。</li>',
            'zh-Hant': '<li>安裝 CLI，然後 <code>supabase login</code> 和 <code>supabase link</code> 連接到您的專案。</li><li>添加密鑰：Dashboard → Functions → Secrets → <code>OPENAI_API_KEY</code>（可選 <code>OPENAI_MODEL</code>）。</li><li>部署：<code>supabase functions deploy ai-patient-draft</code></li><li>使用樂意中已有的 anon key / 專案 URL（無需更改金鑰）。</li>'
        },
        'ai.settings.loginTightenHtml': {
            en: 'Drafting works for anyone by default (<strong>no login check</strong>). Opt-in tightening: add secret <code>AI_REQUIRE_LOGIN=true</code> so only active <code>app_users</code> can call OpenAI via this route.',
            'zh-CN': '默认任何人可使用草稿功能（<strong>不检查登录</strong>）。可选收紧：添加密钥 <code>AI_REQUIRE_LOGIN=true</code>，仅活跃 <code>app_users</code> 可通过此路由调用 OpenAI。',
            'zh-Hant': '預設任何人可使用草稿功能（<strong>不檢查登入</strong>）。可選收緊：添加密鑰 <code>AI_REQUIRE_LOGIN=true</code>，僅活躍 <code>app_users</code> 可透過此路由呼叫 OpenAI。'
        },
        'common.psNoPatients': { en: 'No patients found', 'zh-CN': '未找到患者', 'zh-Hant': '未找到病人' },
