        'common.patientFallback': { en: 'Patient', 'zh-CN': '患者', 'zh-Hant': '病人' },
        'patient.alertNoFreeRange': {
            en: 'No free patient numbers in range 010000–999999 (shared across all clinics).',
            'zh-CN': '010000–999999 范围内已无可用患者编号（全诊所共用）。',
            'zh-Hant': '010000–999999 範圍內已無可用病人編號（全診所共用）。'
        },
        'ai.pitchHide': { en: 'Hide ↑', 'zh-CN': '收起 ↑', 'zh-Hant': '收起 ↑' },
        'ai.pitchDetailHtml': {
            en: 'Front-desk teams save hours drafting messages while keeping a premium, consistent tone. This module is framed as an add-on: pair it with your subscription tier for differentiation in demos and tenders.',
            'zh-CN': '前台团队可节省大量起草时间，同时保持高端一致的语气。本模块定位为增值组件：与订阅套餐搭配，便于演示和投标差异化。',
            'zh-Hant': '前台團隊可節省大量起草時間，同時保持高端一致的語氣。本模組定位為增值組件：與訂閱套餐搭配，便於演示和投標差異化。'
        },
        'ai.settings.leadHtml': {
            en: '<strong>Default:</strong> the app calls your Supabase project\'s Edge Function <code>ai-patient-draft</code>, which validates the logged-in clinic user server-side and calls OpenAI there (never from the browser). Set <code>OPENAI_API_KEY</code> only in Supabase secrets. If the function is missing or errors, Joyful Smile falls back to the optional HTTPS proxy below, then offline demo templates.',
            'zh-CN': '<strong>默认：</strong>应用调用您 Supabase 项目的 Edge 函数 <code>ai-patient-draft</code>，在服务端校验已登录诊所用户并在该处调用 OpenAI（绝不会在浏览器中）。<code>OPENAI_API_KEY</code> 仅设置在 Supabase 密钥中。若函数缺失或出错，乐意会回退到下方可选 HTTPS 代理，再回退到离线演示模板。',
            'zh-Hant': '<strong>預設：</strong>應用程式呼叫您 Supabase 專案的 Edge 函式 <code>ai-patient-draft</code>，在伺服器端校驗已登入診所使用者並於該處呼叫 OpenAI（絕不會在瀏覽器中）。<code>OPENAI_API_KEY</code> 僅設定在 Supabase 秘密中。若函式缺失或出錯，樂意會回退到下方可選 HTTPS 代理，再回退到離線示範範本。'
        },
        'ai.emptyFilter': { en: 'No patients match these filters.', 'zh-CN': '没有患者符合这些筛选条件。', 'zh-Hant': '沒有病人符合這些篩選條件。' },
